#!/data/data/com.termux/files/usr/bin/bash
# Nulvex Shell Obfuscator output
# Encoding bukan enkripsi kriptografis.
set -euo pipefail

command -v base64 >/dev/null 2>&1 || {
    echo 'Error: base64 tidak ditemukan' >&2
    exit 127
}
command -v python3 >/dev/null 2>&1 || {
    echo 'Error: python3 diperlukan untuk dekompresi' >&2
    exit 127
}

tmp_dir="${TMPDIR:-${PREFIX:-/tmp}/tmp}"
mkdir -p "$tmp_dir"
umask 077
tmp_file="$(mktemp "$tmp_dir/nulvex.XXXXXX")"

cleanup() {
    rm -f "$tmp_file"
}
trap cleanup EXIT
trap 'exit 130' INT
trap 'exit 143' TERM

cat <<'NULVEX_PAYLOAD' | base64 -d | base64 -d | base64 -d | base64 -d | base64 -d | base64 -d | python3 -c 'import sys,zlib;sys.stdout.buffer.write(zlib.decompress(sys.stdin.buffer.read()))' > "$tmp_file"

NULVEX_PAYLOAD

bash "$tmp_file" "$@"
